var ph = PhaseManager.get_current_phase_instance()
var sel = ph.sequencer_11e.peek_selection(GameState.state)
return str(sel.get("player", 0)) + ":" + ",".join(sel.get("candidates", []))

for c in tree.root.get_children():
	if c is AcceptDialog and c.visible:
		var stack = [c]
		while not stack.is_empty():
			var n = stack.pop_back()
			for ch in n.get_children():
				stack.append(ch)
				if ch is Button and str(ch.text) == "Decline":
					ch.pressed.emit()
					return true
return true

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var wl = d.get_node("Content/WeaponList")
var tl = d.get_node("Content/TargetList")
if wl.item_count == 0 or tl.item_count == 0:
	return false
wl.select(0)
wl.item_selected.emit(0)
tl.select(0)
tl.item_selected.emit(0)
return str(d.unit_id) == "U_WARBOSS_T"

